SELECT
  @ofmgeographiccrosswalk.`countyname` AS `countyname`,
  @ofmgeographiccrosswalk.`county` AS `county`,
  iif(`hispanic` = 1, "Hispanic", "Non-Hispanic") AS `hispanic`,
  @ofmracecrosswalk.`label97min` AS `label97min`,
  sum(`pop_2020`) AS `population_2020`,
  sum(`pop_2021`) AS `population_2021`,
  sum(`pop_2022`) AS `population_2022`,
  sum(`pop_2023`) AS `population_2023`,
  sum(`pop_2024`) AS `population_2024`,
  sum(`pop_2025`) AS `population_2025`
LEFT OUTER JOIN @9fmr-fbqq AS @ofmracecrosswalk ON `race97`
                                                     = @ofmracecrosswalk.`race97`
  LEFT OUTER JOIN @pvty-6zcu AS @ofmgeographiccrosswalk ON `block20l`
                                                             = @ofmgeographiccrosswalk.`block20l`
GROUP BY
  @ofmgeographiccrosswalk.`county`,
  @ofmracecrosswalk.`label97min`,
  `hispanic`,
  @ofmgeographiccrosswalk.`countyname`

